function applyFolds(){const wf=!!uiState.sbWatchFolded,rf=!!uiState.sbWriteFolded,wb=document.getElementById('watchFold'),rb=document.getElementById('writeFold');liveBox.classList.toggle('folded',wf);writeBox.classList.toggle('folded',rf);if(wb){wb.innerHTML=wf?EYE_OFF_SVG:EYE_SVG;wb.title=t(wf?'sb.unfoldList':'sb.foldList')}if(rb){rb.innerHTML=rf?EYE_OFF_SVG:EYE_SVG;rb.title=t(rf?'sb.unfoldList':'sb.foldList')}}
function saveSbUi(){uiState.sbExpanded=sbExpanded;if(api&&api.setState)api.setState(uiState)}
function sbWalkLeaves(node,path,cb){if(!node)return;if(node.members){node.members.forEach(m=>sbWalkLeaves(m,path+'.'+m.name,cb))}else if(node.elements){node.elements.forEach(e=>sbWalkLeaves(e,path+'['+e.index+']',cb))}else if('value' in node){cb(path,node)}}
function sbUpdateComposite(name){const tree=latest[name];if(!tree)return;sbWalkLeaves(tree,name,(path,node)=>{const cell=compCells[path];if(cell)cell.textContent=fmt(node.value)})}
function sbNote(container,txt){const n=document.createElement('div');n.className='sb-note';n.textContent=txt;container.appendChild(n)}
function sbRenderLeaf(container,label,typeName,path,watchType){const row=document.createElement('div');row.className='sb-mrow';const nm=document.createElement('span');nm.className='sb-mname';nm.textContent=label;nm.title=path;const ty=document.createElement('span');ty.className='sb-mtype';ty.textContent=typeName||watchType;const val=document.createElement('span');val.className='sb-mval';val.textContent='\u2014';compCells[path]=val;row.append(nm,ty,val);container.appendChild(row)}
function sbRenderLayout(container,layout,path){if(!layout)return;if(layout.kind==='struct'||layout.kind==='union'){const ms=layout.members||[];ms.forEach(m=>{const cp=path+'.'+m.name;if(m.compositeLayout)sbRenderNest(container,m.compositeLayout,m.name,cp);else if(m.watchType)sbRenderLeaf(container,m.name,m.typeName||m.watchType,cp,m.watchType)});if(!ms.length)sbNote(container,t('lw.compositeNoLayout'))}else if(layout.kind==='array'){const et=layout.elementType||{},total=Number(layout.totalElements)||0;if(!et.watchType&&!et.compositeLayout){sbNote(container,t('lw.compositeNoLayout'));return}const shown=Math.min(total,16);for(let i=0;i<shown;i++){const p=path+'['+i+']';if(et.compositeLayout)sbRenderNest(container,et.compositeLayout,'['+i+']',p);else sbRenderLeaf(container,'['+i+']',et.typeName||et.watchType,p,et.watchType)}if(total>shown)sbNote(container,t('lw.arrayMore',{n:total-shown}))}}
function sbRenderNest(container,layout,fieldName,path){const wrap=document.createElement('div');const head=document.createElement('div');head.className='sb-comp-head';const arrow=document.createElement('span');arrow.className='sb-arrow';arrow.textContent='\u25B6';const nm=document.createElement('span');nm.className='sb-comp-name';nm.textContent=fieldName;const ty=document.createElement('span');ty.className='sb-comp-type';ty.textContent=layout.typeName||'';head.append(arrow,nm,ty);const body=document.createElement('div');body.className='sb-members';head.onclick=()=>{const open=body.classList.toggle('open');arrow.classList.toggle('open',open)};sbRenderLayout(body,layout,path);wrap.append(head,body);container.appendChild(wrap)}
function sbRenderComposite(item){const row=document.createElement('div');row.className='value-row composite'+(sbExpanded[item.name]?' open':'');const head=document.createElement('div');head.className='sb-comp-head';const arrow=document.createElement('span');arrow.className='sb-arrow'+(sbExpanded[item.name]?' open':'');arrow.textContent='\u25B6';const nm=document.createElement('span');nm.className='sb-comp-name';nm.textContent=item.name;const lay=item.compositeLayout||{};const ty=document.createElement('span');ty.className='sb-comp-type';ty.textContent=lay.typeName||'';const sp=document.createElement('span');sp.className='sb-comp-sp';const rm=document.createElement('button');rm.className='watch-remove';rm.textContent='\u2715';rm.title=t('sb.removeFromWatch');rm.onclick=(e)=>{e.stopPropagation();sbRemove(item.name,true);renderValues();renderAvailable();saveSideWatch();saveSbUi()};head.append(arrow,nm,ty,sp,rm);const body=document.createElement('div');body.className='sb-body';head.onclick=()=>{sbExpanded[item.name]=!sbExpanded[item.name];row.classList.toggle('open',sbExpanded[item.name]);arrow.classList.toggle('open',sbExpanded[item.name]);saveSbUi()};sbRenderLayout(body,lay,item.name);row.append(head,body);liveBox.appendChild(row);sbUpdateComposite(item.name)}
function sbOnComposite(samples){(samples||[]).forEach(s=>{if(s&&s.name)latest[s.name]=s.tree});sideWatch.forEach(it=>{if(sbIsComposite(it))sbUpdateComposite(it.name)})}
function updateValues(samples){(samples||[]).forEach(s=>latest[s.name]=s.value);document.querySelectorAll('[data-value-name]').forEach(el=>el.textContent=fmt(latest[el.dataset.valueName]));syncWriteValues()}
// 采样运行时写入卡片实时同步当前值；用户正在编辑（聚焦/写入在途/防抖中）的卡片不覆盖
function syncWriteValues(){if(!liveRunning)return;writeList.forEach(item=>{const c=writeCells[item.name];if(!c)return;if(writeTimers[item.name])return;if(c.input.classList.contains('pending'))return;const ae=document.activeElement;if(ae===c.input||ae===c.slider)return;let v=Number(latest[item.name]);if(!Number.isFinite(v))return;if(item.type!=='f32')v=Math.round(v);c.setVal(v)})}
function liveStatus(m){m=m||{};lastLive=m;const wasRunning=liveRunning;if(typeof m.running==='boolean')liveRunning=m.running;if(liveLabel.hasAttribute('data-i18n'))liveLabel.removeAttribute('data-i18n');liveToggle.textContent=liveRunning?t('sb.stop'):t('sb.start');liveState.className='live-state '+(m.error?'err':liveRunning?'on':'');liveLabel.textContent=msgText(m)||(liveRunning?t('sb.sampling'):t('sb.stopped'));if(wasRunning!==liveRunning)renderWrites()}
function openocdStatus(m){m=m||{};lastOpenocd=m;const k=m.state||'checking',busy=k==='checking'||k==='installing';openocdCard.className='openocd-card '+k;openocdCard.style.display=k==='ready'?'none':'';openocdMessage.textContent=msgText(m)||t('oc.checking');openocdInstall.style.display=m.canInstall===false?'none':'';openocdCard.querySelectorAll('button').forEach(b=>b.disabled=busy)}
function renderSkillStatus(m){lastSkill=m||lastSkill;const el=document.getElementById('skillStatus');if(!el)return;const status=lastSkill||{},state=status.state||'checking',keys={outdated:'skill.outdated',modified:'skill.modified',notInstalled:'skill.notInstalled',noWorkspace:'skill.noWorkspace',checking:'skill.checking'};const hasCount=Number.isFinite(status.installed)&&Number.isFinite(status.total)&&status.total>0;const label=state==='installed'&&hasCount?t('skill.statusInstalled'):state==='partial'&&hasCount?t('skill.statusPartial'):t(keys[state]||'skill.partial',status);el.textContent='';const labelEl=document.createElement('span');labelEl.className='skill-status-label';labelEl.textContent=label;el.appendChild(labelEl);if(hasCount){const countEl=document.createElement('strong');countEl.className='skill-status-count';countEl.textContent=status.installed+'/'+status.total;el.appendChild(countEl)}el.title=status.skills?status.skills.map(s=>s.name+': '+s.state).join('\\n'):'';el.classList.toggle('accent',state==='installed')}
function progress(m){setStat(m.level==='error'?'error':m.level==='success'?'ready':'',m.key||'',m.params,m.message);logEvents.push({level:m.level,key:m.key,params:m.params,message:m.message});while(logEvents.length>6)logEvents.shift();const line=document.createElement('div');line.className=m.level||'';line.textContent='• '+msgText(m);log.appendChild(line);while(log.children.length>6)log.firstChild.remove()}
function chipEsc(t){return String(t==null?'':t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function chipStatus(m){m=m||{};lastChip=m;const st=m.state||'idle';chipState.className='chip-state '+(st==='error'?'err':st==='ready'?'on':st==='reading'?'busy':'');if(chipRead){chipRead.disabled=st==='reading';chipRead.textContent=st==='reading'?t('sb.readingEllipsis'):(chipHasData?t('sb.reread'):t('sb.read'))}chipLabel.textContent=chipStatusLabel(st);if(st==='error'&&!chipHasData){chipBody.textContent='';const n=document.createElement('div');n.className='chip-note chip-err';n.textContent=msgText(m)||t('chip.stError');chipBody.appendChild(n)}}
function chipStat(label,value){return value?'<div class="chip-stat"><span class="chip-k">'+label+'</span><span class="chip-v" title="'+chipEsc(value)+'">'+chipEsc(value)+'</span></div>':''}
function chipRow(k,v,opt){opt=opt||{};if(!v&&!opt.always)return '';const cls=opt.muted?' muted':'';const copy=opt.copy?'<button class="chip-copy" data-copy="'+chipEsc(opt.copy)+'">'+t('common.copy')+'</button>':'';return '<div class="chip-row"><span class="k">'+k+'</span><span class="v'+cls+'" title="'+chipEsc(v||'—')+'">'+chipEsc(v||'—')+'</span>'+copy+'</div>'}
function chipProbe(info){return [info.probeName||info.probe,info.transport].filter(Boolean).join(' · ')}
